import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:n+1]]
    s = input_data[n+1]

    allowed = set(s)

    if n == 1:
        print(a[0])
        return

    ops = []

    if '*' in allowed:
        if '+' in allowed or '-' in allowed:
            if 0 in a or 1 in a:
                has_zero_or_one = True
            else:
                has_zero_or_one = False

            if has_zero_or_one:
                if '+' in allowed:
                    op = '+'
                else:
                    op = '-'
            else:
                op = '*'

            for _ in range(n - 1):
                ops.append(op)
        else:
            for _ in range(n - 1):
                ops.append('*')
    elif '+' in allowed:
        if '-' in allowed:
            if 0 in a:
                op = '+'
            else:
                op = '-'
            for _ in range(n - 1):
                ops.append(op if op != '-' or 0 in a else '-')
        else:
            for _ in range(n - 1): 
                ops.append('+')
    else:
        for _ in range(n - 1):
            ops.append('-')

    result = []
    for i in range(n):
        result.append(str(a[i]))
        if i < n - 1:
            result.append(ops[i])

    print("".join(result))

if __name__ == "__main__":
    main()
